export function timelineOf(p: Pick<PersonView, 'grades' | 'holds' | 'retiredFrom' | 'pastRetirements'>,
                           claims: readonly TimelineClaim[]): string[] {
  const entries: { date: string; kind: number; order: number; text: string }[] = [];
